erp.cancel_unpaid_payroll(uuid,text):
CREATE OR REPLACE FUNCTION erp.cancel_unpaid_payroll(p_payroll_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.payroll_settlements%rowtype;
  r record;
begin
  perform erp.require_owner_admin();
  if nullif(trim(p_reason),'') is null then raise exception 'Cancellation reason is required'; end if;
  select * into p from erp.payroll_settlements where id=p_payroll_id for update;
  if p.id is null then raise exception 'Payroll not found'; end if;
  if p.status='PAID' then raise exception 'Paid payroll requires a dedicated financial reversal, not unpaid cancellation'; end if;
  if p.status='REVERSED' then return; end if;
  if p.status not in ('DRAFT','CALCULATED','REVIEW','APPROVED') then raise exception 'Payroll cannot be cancelled in status %',p.status; end if;
  perform erp._cp3_lock_business_period(p.period_start,p.period_end);
  perform cp7_attendance_choice.assert_payroll_unclaimed_v1(p.id);

  if exists(
    select 1 from erp.attendance_hpp_pool_sources s
    join erp.attendance_hpp_pools hp on hp.id=s.pool_id
    where s.payroll_id=p.id and hp.status='ACTIVE'
  ) then
    raise exception 'PAYROLL_CONSUMED_BY_ACTIVE_HPP_POOL: cancel the active attendance HPP pool first';
  end if;

  for r in
    select je.id from erp.journal_entries je
    where je.source_id=p.id
      and je.source_type in ('PAYROLL_ATTENDANCE_ACCRUAL','PAYROLL_EXTRA_ACCRUAL','PAYROLL_MANUAL_REDUCTION')
      and je.status='POSTED'
    order by je.posting_at desc,je.id desc
  loop perform erp._cp3_r4_reverse_journal_internal(r.id,p_reason); end loop;

  update erp.payroll_settlements set status='REVERSED',settled_at=null,updated_at=statement_timestamp() where id=p.id;
  for r in select distinct pd.contractor_issue_item_id id from erp.payroll_deductions pd
           where pd.payroll_id=p.id and pd.contractor_issue_item_id is not null
  loop perform erp.refresh_contractor_issue_payroll_status(r.id); end loop;
  for r in select distinct pr.source_id id from erp.payroll_reimbursements pr
           where pr.payroll_id=p.id and pr.source_type='ACCESSORY_BOM' and pr.source_id is not null
  loop
    update erp.contractor_accessory_reimbursement_entitlements e
    set payroll_status=case
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status='PAID') then 'SETTLED'
      when exists(select 1 from erp.payroll_reimbursements pr2 join erp.payroll_settlements ps2 on ps2.id=pr2.payroll_id
                  where pr2.source_type='ACCESSORY_BOM' and pr2.source_id=e.id and ps2.status<>'REVERSED') then 'ALLOCATED'
      else 'UNALLOCATED' end
    where e.id=r.id;
  end loop;
  insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
  values('payroll_settlements',p.id,'CANCEL_UNPAID',jsonb_build_object('previous_status',p.status),erp.current_app_user_id(),p_reason);
end;
$function$

cp7_sales.command(text,jsonb,uuid,text):
CREATE OR REPLACE FUNCTION cp7_sales.command(p_action text, p_payload jsonb, p_request uuid, p_expected text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a jsonb;old cp7_sales.requests;r jsonb;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'CP7_FRESH_ACCESS_REQUIRED';end if;
 a:=cp7_sales.command_access(p_action);
 if p_request is null or (p_action='CREATE' and p_expected is not null) or(p_action<>'CREATE' and(p_expected is null or p_expected!~'^[1-9][0-9]{0,18}$')) then raise exception 'CP7_SALES_COMMAND_FIELDS';end if;
 if p_action in('CREATE','EDIT') then
  perform cp7_sales.validate_draft(p_payload,p_action='EDIT');
 elsif p_action in('PAYMENT','PAYMENT_REVERSE') then
  perform cp7_sales.validate_payment(p_payload,p_action='PAYMENT_REVERSE');
 elsif p_action in('RETURN','RETURN_REVERSE') then
  perform cp7_sales.validate_return(p_payload,p_action='RETURN_REVERSE');
 else
  if jsonb_typeof(p_payload) is distinct from 'object' or not p_payload ?& array['sale_id','review_token','change_reason']
   or exists(select 1 from jsonb_each(p_payload) e where e.key not in('sale_id','review_token','change_reason') or jsonb_typeof(e.value)<>'string')
   or coalesce(p_payload->>'sale_id','')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
   or coalesce(p_payload->>'review_token','')!~'^[a-f0-9]{32}$'
   or length(btrim(p_payload->>'change_reason')) not between 5 and 1000 then raise exception 'CP7_SALES_COMMAND_FIELDS';end if;
 end if;
 insert into cp7_sales.requests values(auth.uid(),p_request,p_action,p_payload,p_expected,null) on conflict do nothing;
 select * into old from cp7_sales.requests where actor=auth.uid() and request_id=p_request for update;
 if old.action<>p_action or old.payload is distinct from p_payload or old.expected_version is distinct from p_expected then raise exception 'CP7_SALES_REQUEST_CHANGED';end if;
 if cp7_sales.command_access(p_action) is distinct from a then raise exception using errcode='42501',message='CP7_SALES_ACCESS_CHANGED';end if;
 if old.response is not null then return old.response;end if;
 insert into cp7_sales.command_context values(pg_backend_pid(),txid_current(),auth.uid(),(p_payload->>'sale_id')::uuid,p_action);
 r:=cp7_sales.apply_command(p_action,p_payload,p_request,p_expected);
 delete from cp7_sales.command_context where backend_pid=pg_backend_pid() and transaction_id=txid_current();
 if cp7_sales.command_access(p_action) is distinct from a then raise exception using errcode='42501',message='CP7_SALES_ACCESS_CHANGED';end if;
 r:=r||jsonb_build_object('contract_version','cp7.sales-outcome.v1','kind','COMMITTED_OUTCOME','action',p_action,'request_id',p_request);
 update cp7_sales.requests set response=r where actor=auth.uid() and request_id=p_request;
 return r;
end $function$

erp.post_journal(text,uuid,date,text,jso:
CREATE OR REPLACE FUNCTION erp.post_journal(p_source_type text, p_source_id uuid, p_transaction_date date, p_description text, p_lines jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public'
AS $function$
declare
  v_entry_id uuid;
  v_input_debit numeric;
  v_input_credit numeric;
  v_cent_lines jsonb := '[]'::jsonb;
  v_number text;
  v_debit numeric(20,2);
  v_credit numeric(20,2);
  r jsonb;
  v_account_id uuid;
  v_gl_date date;
  v_ap_vendor_account uuid;
  v_vendor_id uuid;
  v_vendor_balance numeric(24,6);
  v_vendor_delta numeric(24,6);
begin
  perform erp.require_internal();
  if jsonb_typeof(p_lines) is distinct from 'array' then
    raise exception 'JOURNAL_LINES_ARRAY_REQUIRED';
  end if;
  if jsonb_array_length(p_lines)<2 then
    raise exception 'Journal requires at least two lines';
  end if;
  -- Canonicalize each monetary line exactly as it will be stored. All balance
  -- and vendor-admission checks below consume these same cent amounts.
  for r in select * from jsonb_array_elements(p_lines) loop
    if jsonb_typeof(r) is distinct from 'object' then
      raise exception 'JOURNAL_LINE_OBJECT_REQUIRED';
    end if;
    v_input_debit:=coalesce((r->>'debit')::numeric,0);
    v_input_credit:=coalesce((r->>'credit')::numeric,0);
    if v_input_debit::text in('NaN','Infinity','-Infinity')
       or v_input_credit::text in('NaN','Infinity','-Infinity')
       or v_input_debit<0 or v_input_credit<0 then
      raise exception 'JOURNAL_FINITE_NONNEGATIVE_MONEY_REQUIRED';
    end if;
    v_cent_lines:=v_cent_lines||jsonb_build_array(r||jsonb_build_object(
      'debit',round(v_input_debit,2),'credit',round(v_input_credit,2)));
  end loop;
  p_lines:=v_cent_lines;
  select coalesce(sum(coalesce((x->>'debit')::numeric,0)),0),coalesce(sum(coalesce((x->>'credit')::numeric,0)),0)
  into v_debit,v_credit from jsonb_array_elements(p_lines) x;
  if v_debit<>v_credit or v_debit<=0 then raise exception 'Journal is not balanced. Debit %, Credit %',v_debit,v_credit; end if;
  if exists(select 1 from erp.journal_entries where source_type=p_source_type and source_id=p_source_id and status='POSTED') then
    raise exception 'A posted journal already exists for this source';
  end if;

  -- Serialize journal posting with accounting close/reopen. A close that starts
  -- first blocks this journal until the new closed-through date is visible; a
  -- journal that starts first keeps the close waiting until this posting commits.
  perform 1 from erp.accounting_period_control where singleton_id=1 for share;

  -- Vendor AP is allowed to reach zero, but not become negative. Negative AP
  -- means the company has a receivable/advance from the vendor and requires a
  -- separate explicit workflow instead of silently crossing the account sign.
  v_ap_vendor_account:=erp.account_id('AP_VENDOR');
  for v_vendor_id in
    select distinct nullif(x->>'vendor_id','')::uuid
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','') is not null
      and coalesce((x->>'debit')::numeric,0)>coalesce((x->>'credit')::numeric,0)
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      )
    order by 1
  loop
    perform pg_advisory_xact_lock(hashtextextended('VENDOR_AP|'||v_vendor_id::text,0));

    select coalesce(sum(jl.credit-jl.debit),0)
      into v_vendor_balance
    from erp.journal_lines jl
    join erp.journal_entries je on je.id=jl.journal_entry_id
    where je.status in ('POSTED','REVERSED')
      and jl.account_id=v_ap_vendor_account
      and jl.vendor_id=v_vendor_id;

    select coalesce(sum(
      coalesce((x->>'credit')::numeric,0)-coalesce((x->>'debit')::numeric,0)
    ),0)
      into v_vendor_delta
    from jsonb_array_elements(p_lines) x
    where nullif(x->>'vendor_id','')::uuid=v_vendor_id
      and (
        (x ? 'mapping_key' and x->>'mapping_key'='AP_VENDOR')
        or (x ? 'account_id' and nullif(x->>'account_id','')::uuid=v_ap_vendor_account)
      );

    if v_vendor_balance::text in('NaN','Infinity','-Infinity') or v_vendor_balance+v_vendor_delta < 0 then
      raise exception 'Transaksi ini membuat hutang vendor menjadi negatif. Hutang saat ini %, perubahan %, hasil %. Reverse/koreksi pembayaran, claim, atau invoice terkait dulu; kelebihan bayar/claim vendor harus masuk workflow piutang vendor terpisah.',
        round(v_vendor_balance,2),round(v_vendor_delta,2),round(v_vendor_balance+v_vendor_delta,2);
    end if;
  end loop;

  v_gl_date:=erp.resolve_accounting_transaction_date(p_transaction_date);
  v_number:='JRN-'||to_char((clock_timestamp() AT TIME ZONE 'Asia/Jakarta'),'YYYYMMDDHH24MISSMS')||'-'||substr(gen_random_uuid()::text,1,8);
  insert into erp.journal_entries(journal_number,economic_date,transaction_date,posting_at,source_type,source_id,description,status,created_by)
  values(v_number,p_transaction_date,v_gl_date,statement_timestamp(),p_source_type,p_source_id,p_description,'POSTED',erp.current_app_user_id()) returning id into v_entry_id;

  for r in select * from jsonb_array_elements(p_lines) loop
    if r?'account_id' then v_account_id:=(r->>'account_id')::uuid; else v_account_id:=erp.account_id(r->>'mapping_key'); end if;
    insert into erp.journal_lines(journal_entry_id,account_id,description,debit,credit,customer_id,vendor_id,contractor_id,po_id,product_id)
    values(v_entry_id,v_account_id,r->>'description',coalesce((r->>'debit')::numeric,0),coalesce((r->>'credit')::numeric,0),nullif(r->>'customer_id','')::uuid,nullif(r->>'vendor_id','')::uuid,nullif(r->>'contractor_id','')::uuid,nullif(r->>'po_id','')::uuid,nullif(r->>'product_id','')::uuid);
  end loop;

  insert into erp.account_daily_balances(balance_date,account_id,debit_total,credit_total)
  select v_gl_date,jl.account_id,sum(jl.debit),sum(jl.credit) from erp.journal_lines jl where jl.journal_entry_id=v_entry_id group by jl.account_id
  on conflict(balance_date,account_id) do update set debit_total=erp.account_daily_balances.debit_total+excluded.debit_total,credit_total=erp.account_daily_balances.credit_total+excluded.credit_total,updated_at=statement_timestamp();

  if v_gl_date<>p_transaction_date then
    insert into erp.audit_logs(entity_type,entity_id,action,new_data,changed_by,change_reason)
    values('journal_entries',v_entry_id,'POST',jsonb_build_object('economic_date',p_transaction_date,'transaction_date',v_gl_date,'period_shifted',true,'source_type',p_source_type,'source_id',p_source_id),erp.current_app_user_id(),'Late/backdated posting moved to open accounting period');
  end if;
  return v_entry_id;
end;
$function$

cp7_credit.current_effective_paid(uuid):
CREATE OR REPLACE FUNCTION cp7_credit.current_effective_paid(p_sale uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
 SET "TimeZone" TO 'UTC'
AS $function$
declare paid numeric;adjustment numeric;
begin
 select coalesce(sum(amount),0)into paid from erp.sales_payments where sale_id=p_sale and status='POSTED';
 adjustment:=erp._cp7_current_credit_adjustment(p_sale);
 if paid+adjustment<0 and not cp7_credit.payment_is_intermediate_v1(p_sale)then raise exception 'CP7_CREDIT_NEGATIVE_EFFECTIVE_PAID';end if;
 return paid+adjustment;
end $function$

erp.require_internal():
CREATE OR REPLACE FUNCTION erp.require_internal()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_app_role text;v_jwt_role text;
begin
 if session_user in('postgres','supabase_admin') then return;end if;
 begin v_jwt_role:=coalesce(auth.jwt()->>'role','');exception when others then v_jwt_role:='';end;
 if v_jwt_role='service_role' then return;end if;
 -- R4-05 one context probe (scripts/cp7_internal_guard_bundle.py): without a private command context row of this
 -- backend and transaction no branch below admits; only the final role test decides. A transaction that has
 -- no transaction id yet has written no row (a context row carries the id of the transaction that wrote it).
 if txid_current_if_assigned() is null or not exists(select 1 from cp7_sales.command_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from erp.cutting_bridge_execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from erp.bs_resolution_execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from erp.cp6_laundry_qc_execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_procurement.execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_material.execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_supplier_return.execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_payroll.execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_payroll.settlement_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_attendance.command_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current()
  union all select 1 from cp7_credit.consumer_execution_context x where x.backend_pid=pg_backend_pid() and x.transaction_id=txid_current())then
  if coalesce(erp.current_app_role(),'') not in('OWNER','ADMIN','STAFF') then raise exception 'Internal ERP access required';end if;
  return;
 end if;
 if exists(select 1 from cp7_sales.command_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and c.action in('CREATE','EDIT','POST','CANCEL','PAYMENT','PAYMENT_REVERSE','RETURN','RETURN_REVERSE','SALE_REVERSE')
   and not exists(select 1 from erp.cutting_bridge_execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from erp.bs_resolution_execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from erp.cp6_laundry_qc_execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from cp7_procurement.execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from cp7_material.execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from cp7_supplier_return.execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from cp7_payroll.execution_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from cp7_payroll.settlement_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current() union all select 1 from cp7_attendance.command_context before_sales where before_sales.backend_pid=pg_backend_pid() and before_sales.transaction_id=txid_current())
   then cp7_sales.command_allowed(c.action) else false end) then return;end if;

 -- Keep indexable identity filters, and evaluate live scope permissions only
 -- for that exact candidate. SQL AND does not fix predicate evaluation order.
 -- Matched scope checks and the existing legacy fallback remain unchanged.
 if exists(select 1 from erp.cutting_bridge_execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor_key=erp._idempotency_actor_key() and c.action='POST_CUTTING'
   and c.permission_key='production.cutting.post' then erp.has_permission(c.permission_key) else false end) then return;end if;
 if exists(select 1 from erp.bs_resolution_execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor_key=erp._idempotency_actor_key()
   and c.permission_key in('production.bs_rework.create','production.bs_rework.post','production.bs_rework.reverse')
   then erp.has_permission(c.permission_key) else false end) then return;end if;
 if exists(select 1 from erp.cp6_laundry_qc_execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor_key=erp._idempotency_actor_key()
   and ((c.action in('POST_DELIVERY','POST_RECEIPT','POST_FAILED_WASH') and c.permission_key='production.laundry.post')
    or(c.action='POST_FINAL_SKU' and c.permission_key='production.final_sku.post')
    or(c.action in('REVERSE_DELIVERY','REVERSE_RECEIPT') and c.permission_key='production.laundry.reverse')
    or(c.action='REVERSE_FINAL_SKU' and c.permission_key='production.final_sku.reverse'))
   then erp.has_permission(c.permission_key) else false end) then return;end if;
 -- Only a private, transaction/actor-bound public-command context extends the
 -- legacy internal-role guard. Caller-controlled GUCs cannot grant this path.
 if exists(select 1 from cp7_procurement.execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and ((c.action='SAVE_DRAFT' and c.permission_key='warehouse.procurement.create')
    or(c.action='POST' and c.permission_key='warehouse.procurement.post'))
   then erp.has_permission('warehouse.procurement.view') and erp.has_permission(c.permission_key) else false end) then return;end if;
 if exists(select 1 from cp7_material.execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and c.action in('SAVE_TRANSFER','POST_TRANSFER','REVERSE_TRANSFER','SAVE_COUNT','POST_COUNT','DELETE_COUNT','REVERSE_COUNT') and c.permission_key='warehouse.stock.adjust'
   then erp.has_permission('warehouse.material.view') and erp.has_permission(c.permission_key) else false end) then return;end if;
 if exists(select 1 from cp7_supplier_return.execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and ((c.action='SAVE' and c.permission_key='warehouse.procurement.create')
    or(c.action in('POST','REVERSE') and c.permission_key='warehouse.procurement.reverse'))
   then erp.has_permission('warehouse.procurement.view') and erp.has_permission(c.permission_key) else false end) then return;end if;
 if exists(select 1 from cp7_payroll.execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and c.action='POST_NOTE' and c.permission_key='production.fg_handoff.post'
   then erp.has_permission('production.fg_handoff.view') and erp.has_permission(c.permission_key) else false end) then return;end if;
  if exists(select 1 from cp7_payroll.settlement_context c where c.backend_pid=pg_backend_pid()
    and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
     and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
    then erp.has_permission('finance.payroll.view')
    and(c.action not in('PREPARE','APPROVE','CANCEL','REVERSE') or erp.has_permission('finance.payroll.approve'))
    and(c.action not in('PAY','REVERSE') or erp.has_permission('finance.payroll.pay'))
    else false end) then return;end if;
  if exists(select 1 from cp7_attendance.command_context c where c.backend_pid=pg_backend_pid()
    and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
     and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
    then erp.has_permission('finance.attendance.view') and erp.has_permission(c.permission)
    and(not c.owner_required or erp.current_app_role() in('OWNER','ADMIN'))
    else false end) then return;end if;
 if exists(select 1 from cp7_sales.command_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and c.action in('CREATE','EDIT','POST','CANCEL','PAYMENT','PAYMENT_REVERSE','RETURN','RETURN_REVERSE','SALE_REVERSE')
   then cp7_sales.command_allowed(c.action) else false end) then return;end if;
 if exists(select 1 from cp7_credit.consumer_execution_context c where c.backend_pid=pg_backend_pid()
  and c.transaction_id=txid_current() and case when c.backend_pid=pg_backend_pid()
   and c.transaction_id=txid_current() and c.actor=auth.uid() and v_jwt_role='authenticated'
   and c.phase in('LOCKED','POSTING','MATERIALIZED','COMPLETE')
   then cp7_credit.consumer_internal_allowed_v1() else false end) then return;end if;
 v_app_role:=erp.current_app_role();
 if coalesce(v_app_role,'') not in('OWNER','ADMIN','STAFF') then raise exception 'Internal ERP access required';end if;
end $function$

cp7_sales.command_access(text):
CREATE OR REPLACE FUNCTION cp7_sales.command_access(p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;
begin
 -- Read the complete current access once per invocation. access_now() already
 -- obtains that same document; invoking it here and then reading it again
 -- multiplies full permission-list reads in each native account/HPP guard.
 -- This is never a command/transaction cache: every post-wait guard invocation
 -- still reads current authority and calls the native fine permission checks.
 if auth.uid() is null or coalesce(auth.jwt()->>'role','')<>'authenticated' then raise exception using errcode='42501',message='CP7_SALES_ACCESS_DENIED';end if;
 a:=erp.get_my_access_v1();
 if a->'allowed' is distinct from 'true'::jsonb or not erp.has_permission('sales.invoice.view') then raise exception using errcode='42501',message='CP7_SALES_ACCESS_DENIED';end if;
 if not erp.has_permission('finance.ar.view') or p_action is null or p_action not in('CREATE','EDIT','POST','CANCEL','PAYMENT','PAYMENT_REVERSE','RETURN','RETURN_REVERSE','SALE_REVERSE')
  or not erp.has_permission(case when p_action='POST' then 'sales.invoice.post' when p_action='CREATE' then 'sales.invoice.create' when p_action='PAYMENT' then 'sales.payment.create' when p_action='PAYMENT_REVERSE' then 'sales.payment.reverse' when p_action='RETURN' then 'sales.return.create' when p_action='RETURN_REVERSE' then 'sales.return.reverse' when p_action='SALE_REVERSE' then 'sales.invoice.reverse' else 'sales.invoice.edit_draft' end)
  or(p_action in('PAYMENT','PAYMENT_REVERSE') and not erp.has_permission('sales.payment.view'))
  or(p_action='PAYMENT' and not erp.has_permission('sales.payment.post'))
  or(p_action in('RETURN','RETURN_REVERSE') and not erp.has_permission('sales.return.view'))
  or(p_action='RETURN' and not erp.has_permission('sales.return.post'))
 then raise exception using errcode='42501',message='CP7_SALES_WRITE_DENIED';end if;
 if p_action in('PAYMENT_REVERSE','RETURN_REVERSE','SALE_REVERSE') and coalesce(a->'profile'->>'role_code','') not in('OWNER','ADMIN') then raise exception using errcode='42501',message='CP7_SALES_OWNER_ADMIN_REQUIRED';end if;
 return a;
end $function$

cp7_installment.access_now(text):
CREATE OR REPLACE FUNCTION cp7_installment.access_now(p_action text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;
begin
 if auth.uid()is null or coalesce(auth.jwt()->>'role','')<>'authenticated' then raise exception using errcode='42501',message='CP7_INSTALLMENT_ACCESS_DENIED';end if;
 a:=erp.get_my_access_v1();
 if a->'allowed'is distinct from 'true'::jsonb or not erp.has_permission('finance.payroll.view')
  or(p_action is not null and(p_action not in('PAY','REVERSE_PAYMENT','REVERSE_PAYROLL')or not erp.has_permission('finance.payroll.pay')))
  or(p_action='REVERSE_PAYROLL'and not erp.has_permission('finance.payroll.approve'))then raise exception using errcode='42501',message='CP7_INSTALLMENT_ACCESS_DENIED';end if;
 return a;
end $function$

erp.get_my_access_v1():
CREATE OR REPLACE FUNCTION erp.get_my_access_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_auth_user_id uuid:=auth.uid();v_user erp.app_users%rowtype;v_role erp.app_roles%rowtype;
begin
  if v_auth_user_id is null then
    return jsonb_build_object('allowed',false,'reason','AUTH_REQUIRED');
  end if;
  select * into v_user from erp.app_users where auth_user_id=v_auth_user_id limit 1;
  if v_user.id is null then
    return jsonb_build_object('allowed',false,'reason','APP_USER_NOT_FOUND');
  end if;
  if not v_user.is_active then
    return jsonb_build_object('allowed',false,'reason','APP_USER_INACTIVE');
  end if;
  select * into v_role from erp.app_roles where id=v_user.role_id;
  if v_role.id is null then
    return jsonb_build_object('allowed',false,'reason','APP_ROLE_NOT_FOUND');
  end if;
  if not v_role.is_active then
    return jsonb_build_object('allowed',false,'reason','APP_ROLE_INACTIVE');
  end if;
  return jsonb_build_object(
    'allowed',true,
    'profile',jsonb_build_object(
      'id',v_user.id,'auth_user_id',v_user.auth_user_id,'full_name',v_user.full_name,
      'role_id',v_role.id,'role_code',v_role.role_code,'role_name',v_role.role_name,
      'is_active',v_user.is_active,'row_version',v_user.row_version,
      'role_row_version',v_role.row_version
    ),
    'permissions',erp.role_permission_keys(v_role.id),
    'external_portals',jsonb_build_object('mandor','NOT CONNECTED','laundry','NOT CONNECTED','store','NOT CONNECTED')
  );
end
$function$

erp.has_permission(text):
CREATE OR REPLACE FUNCTION erp.has_permission(p_permission_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_jwt_role text;v_allowed boolean:=false;
begin
  begin
    v_jwt_role:=coalesce(auth.jwt()->>'role','');
  exception when others then
    v_jwt_role:='';
  end;
  if v_jwt_role='service_role' then return true; end if;
  select case
    when r.is_protected and r.role_code='OWNER' then true
    else exists(
      select 1
      from erp.app_role_permissions rp
      join erp.app_permissions p on p.permission_key=rp.permission_key and p.is_active
      where rp.role_id=r.id and rp.permission_key=p_permission_key
    ) end
  into v_allowed
  from erp.app_users u
  join erp.app_roles r on r.id=u.role_id and r.is_active
  where u.auth_user_id=auth.uid() and u.is_active
  limit 1;
  return coalesce(v_allowed,false);
end
$function$
